WITH session_summary AS (SELECT session_id, SUM(CASE WHEN event_type = 'page_view' THEN duration_sec ELSE 0 END) AS page_view_duration_sec FROM web_events GROUP BY session_id) SELECT s.id, s.browser, s.started_at, ss.page_view_duration_sec FROM sessions s LEFT OUTER JOIN session_summary ss ON s.id = ss.session_id WHERE ss.page_view_duration_sec >= 28 ORDER BY s.browser;
